ALTER TABLE "rang" DROP CONSTRAINT "rang_reihenfolge_pro_einheit";--> statement-breakpoint
ALTER TABLE "rang" ADD CONSTRAINT "rang_reihenfolge_pro_einheit" UNIQUE("einheit_id","typ","reihenfolge");--> statement-breakpoint
-- Jede Einheit hat die Schweizer Dienstgrade als Ränge vom Typ miliz (wie MILIZ_RAENGE in einheiten.ts); die Reihenfolge zählt je Typ.
-- Einheiten, die schon einen Rang vom Typ miliz haben, bleiben unverändert.
INSERT INTO "rang" ("einheit_id", "name", "kuerzel", "typ", "reihenfolge", "abzeichen_bild", "abzeichen_bild_typ")
SELECT e."id", g."name", g."kuerzel", 'miliz', g."n" * 10, convert_to(g."svg", 'UTF8'), 'svg'
FROM "einheit" e
CROSS JOIN (VALUES
  (1, 'Oberst', 'Oberst', '<svg xmlns="http://www.w3.org/2000/svg" viewBox="-230.36957692307692 102.85 1166.5661538461538 1516.536"><g id="Ebene_1"><g><path d="M0,1516.536h705.827V205.7H0V1516.536z"/><path fill="#EDD010" d="M0,1437.167h705.827v-144.567H0V1437.167z"/><path fill="#EDD010" d="M705.826,1080H0v144.566h705.826V1080z"/></g><path fill="#EDD010" d="M705.826,867.401H0v144.566h705.826V867.401z"/></g></svg>'),
